<?php
require __DIR__.'/src/commerce.php';require_admin();if(!can_manage('orders')){http_response_code(403);exit('ليس لديك صلاحية إدارة الطلبات');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';if($id&&in_array($status,['new','reviewing','approved','completed','cancelled'],true)){$q=db()->prepare('UPDATE customer_orders SET status=? WHERE id=?');$q->execute([$status,$id]);log_action('admin',(int)$_SESSION['admin_id'],'order_status_changed','order',$id);redirect('admin-orders.php');}}
$q=db()->query('SELECT o.*,c.name,c.email,i.title FROM customer_orders o JOIN customers c ON c.id=o.customer_id JOIN items i ON i.id=o.item_id ORDER BY o.id DESC LIMIT 200');$orders=$q->fetchAll();$labels=['new'=>'جديد','reviewing'=>'مراجعة','approved'=>'مقبول','completed'=>'مكتمل','cancelled'=>'ملغي'];
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css?v=4"><title>إدارة الطلبات | نَسَق</title></head><body><header class="site-header"><nav class="wrap site-nav"><a class="brand" href="admin.php"><span class="brand-mark">ن</span>نَسَق</a><a class="btn secondary" href="admin.php">لوحة الإدارة</a></nav></header><main class="wrap"><section class="pagehead"><h1>طلبات العملاء التجارية</h1><p>متابعة الطلبات وتحديث حالاتها. لا يوجد تحصيل دفع آلي في هذه النسخة.</p></section><div class="tablewrap"><table><tr><th>المرجع</th><th>العميل</th><th>العنصر</th><th>المبلغ</th><th>الحالة</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['reference'])?></td><td><?=e($o['name'])?><br><?=e($o['email'])?></td><td><?=e($o['title'])?></td><td><?=$o['amount']!==null?e(number_format((float)$o['amount'],2)).' ر.س':'—'?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$o['id']?>"><select name="status"><?php foreach($labels as $k=>$v):?><option value="<?=$k?>" <?=$o['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button type="submit">تحديث</button></form></td></tr><?php endforeach;?></table></div></main></body></html>